import{z as l,x as o,o as s,c as d,q as r,j as n,D as e,d as t,s as B,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"风险量化","description":"","frontmatter":{"title":"风险量化","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/risk-quantification.md","filePath":"cs/risk-quantification.md","lastUpdated":1791413859000}'),p={name:"cs/risk-quantification.md"};function c(u,a,F,m,D,h){const i=o("Mermaid");return s(),d("div",null,[a[2]||(a[2]=r('<h1 id="风险量化" tabindex="-1">风险量化 <a class="header-anchor" href="#风险量化" aria-label="Permalink to &quot;风险量化&quot;">​</a></h1><div class="epigraph"><p>风险是频率与损失的语言。FAIR 一类把情景写成可比较的分布，而不是红黄绿。数字差也会误导：没有暴露面与控制，CVSS 不能当唯一输入。</p><footer>—— 据 Freund and Jones, *Measuring and Managing Information Risk*（FAIR）；对照 NIST CSF；[CVE 与 CVSS](/cs/cve-cvss)</footer></div><p>上一课<a href="/cs/usable-security">可用安全</a>说明人会绕过难用的控制；缺口是<strong>决策语言</strong>——把安全情景量化，管理层才能排优先级。本课 FAIR 直觉，不假装精算完成。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>红黄绿的毛病是颜色不可加也不可比：两个黄加起来是什么？FAIR 一类的回答是把每个情景拆成频率与损失幅度两个分布——频率由威胁事件量与抵抗强度（控制多硬）决定，幅度由资产与后果决定，随机模拟卷出年化损失的分布。数据稀疏时不编点估计，给区间。</p><h3 id="不是金融定价" tabindex="-1">不是金融定价 <a class="header-anchor" href="#不是金融定价" aria-label="Permalink to &quot;不是金融定价&quot;">​</a></h3><p>本课不是金融定价：不把期权公式或限价簿搬进来——安全事件没有可连续对冲的市场，这里只借概率语言。</p><p><span class="marginnote">FAIR。零信任下一课是架构响应之一。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是把一条情景从起因写到钱：「勒索软件经 VPN 凭据进入」拆成发生频率分布与单次损失分布（赎金、停机、恢复、合规），合成年化损失分布，再按中位数与尾部排控制优先级。<span class="marginnote">数字实例：频率抽到 3 次，三次幅度分别抽到 5 万、50 万、500 万，这一次模拟的年损失就是 555 万。单次数字没有意义——重复上万次后，555 万落在分布哪个位置才说明问题。</span>对照 CVSS：它只是技术严重度，没有暴露面与资产价值，不能单独当风险。下一课零信任架构。</p>',11)),(s(),n(A,null,{default:e(()=>[B(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SCEN%5B%22%E6%83%85%E6%99%AF%22%5D%20--%3E%20FREQ%5B%22%E9%A2%91%E7%8E%87%22%5D%0A%20%20SCEN%20--%3E%20MAG%5B%22%E6%8D%9F%E5%A4%B1%E5%B9%85%E5%BA%A6%22%5D%0A%20%20FREQ%20--%3E%20RISK%5B%22%E5%8F%AF%E6%AF%94%E8%BE%83%E7%9A%84%E9%A3%8E%E9%99%A9%22%5D%0A%20%20MAG%20--%3E%20RISK%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"机制是给钱与工程之间一个接口：工程师报「控制把情景频率压到多少」，管理层问「这笔钱买回多少期望损失下降」，两边在损失分布上对齐量纲。误差要说实话：频率估计常有数量级的不确定度，量化的价值在可比较与可复核，不在数字精确。零信任是减少情景发生条件的架构。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：蒙特卡洛就像掷一万次骰子记点数分布。不必解析公式推导形状，抽样次数够多，直方图自己画出「年损失长什么样」，包括解析法最难算的那条右尾。")],-1)),(s(),n(A,null,{default:e(()=>[B(i,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E4%BB%8E%E9%A2%91%E7%8E%87%E5%88%86%E5%B8%83%E6%8A%BD%E4%B8%80%E4%B8%AA%E6%A0%B7%E6%9C%AC%EF%BC%9A%E4%BB%8A%E5%B9%B4%E5%8F%91%E7%94%9F%E5%87%A0%E6%AC%A1%22%5D%20--%3E%20LOOP%5B%22%E6%AF%8F%E6%AC%A1%E4%BA%8B%E4%BB%B6%E4%BB%8E%E5%B9%85%E5%BA%A6%E5%88%86%E5%B8%83%E6%8A%BD%E4%B8%80%E4%B8%AA%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20LOOP%20--%3E%20SUM%5B%22%E5%8A%A0%E6%80%BB%E6%88%90%E4%B8%80%E6%AC%A1%E6%A8%A1%E6%8B%9F%E7%9A%84%E5%B9%B4%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20SUM%20--%3E%20REP%5B%22%E9%87%8D%E5%A4%8D%E4%B8%8A%E4%B8%87%E6%AC%A1%EF%BC%8C%E5%BE%97%E5%88%B0%E5%B9%B4%E6%8D%9F%E5%A4%B1%E5%88%86%E5%B8%83%22%5D%0A%20%20REP%20--%3E%20P50%5B%22%E4%B8%AD%E4%BD%8D%E6%95%B0%EF%BC%9A%E5%B9%B3%E5%B8%B8%E5%B9%B4%E4%BB%BD%E5%A4%A7%E6%A6%82%E4%BA%8F%E5%A4%9A%E5%B0%91%22%5D%0A%20%20REP%20--%3E%20P95%5B%2295%20%E5%88%86%E4%BD%8D%EF%BC%9A%E5%9D%8F%E5%B9%B4%E4%BB%BD%E7%9A%84%E5%B0%BE%E9%83%A8%E6%8D%9F%E5%A4%B1%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">常见误区：把年化损失期望值单独当决策依据。两个情景期望值相同，一个年年小亏、一个十年一次巨亏，控制优先级完全不同——要看整个分布尤其尾部，这正是 FAIR 不肯只给一个数的原因。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不编造精确损失表；边界要点名：尾部大额损失恰是数据最稀的地方，报告要带置信区间，不能只给期望值。零信任架构下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可用安全之后，管理层要用可比较的风险。</li><li>情景、频率、幅度；CVSS 只是输入之一。</li><li>稀疏数据用区间，不用假精确。</li><li>下一课零信任架构。</li><li>出处：Freund and Jones, FAIR；NIST CSF；<a href="/cs/cve-cvss">cve-cvss</a>。</li></ul>',5))])}const C=l(p,[["render",c]]);export{S as __pageData,C as default};
